vector<int> countSubgraphsForEachD(int n, vector<pair<int, int>>& edges) {
    vector<vector<int>> tree(n + 1);
    for (auto &edge : edges) {
        tree[edge.first].push_back(edge.second);
        tree[edge.second].push_back(edge.first);
    }

