        for (int child : tree[node]) {
            if (child != parent) depth = max(depth, 1 + dfs(child, node));
        }
        return depth;
    };

    vector<int> ans(n - 1);
    for (int i = 1; i <= n; ++i) {
        int maxD = dfs(i, 0);
        if (maxD > 0) ans[maxD - 1]++;
    }
    return ans;
}
