                int ub = Collections.binarySearch(positions.get(arr[randomIndex]), right + 1);
                if(lb < 0) lb = ~lb;
                if(ub < 0) ub = ~ub;
                if(ub - lb >= threshold) return arr[randomIndex];
            }
        }
        return -1;
    }
