struct ListNode {
    int val;
    ListNode *next;
    ListNode(int x) : val(x), next(NULL) {}
};

ListNode* merge(ListNode* left, ListNode* right){
    if(left == NULL) return right;
    if(right == NULL) return left;
    if(left->val < right->val){
        left->next = merge(left->next, right);
        return left;
