            if (freq > max_freq) {
                max_freq = freq;
                min_length = i - start_map.get(nums[i]) + 1;
            } else if (freq == max_freq) {
                min_length = Math.min(min_length, i - start_map.get(nums[i]) + 1);
            }
        }

        return min_length;
    }
}
