#include <vector>
#include <queue>

using namespace std;

int shortestDistance(vector<vector<int>>& grid) {
    int m = grid.size();
    int n = grid[0].size();

    vector<vector<int>> total_count(m, vector<int>(n, 0));
    vector<vector<int>> dist_sum(m, vector<int>(n, 0));
    int house_count = 0;

    int dirs[4][2] = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (grid[i][j] == 1) {
                house_count++;
                queue<pair<int, int>> q;
                q.push({i, j});
                vector<vector<bool>> visited(m, vector<bool>(n, false));
                int level = 1;
                while (!q.empty()) {
                    int sz = q.size();
                    for (int q_i = 0; q_i < sz; q_i++) {
                        int x = q.front().first;
                        int y = q.front().second;
                        q.pop();
                        for (auto &dir : dirs) {
                            int x_new = x + dir[0];
                            int y_new = y + dir[1];
                            if (x_new >= 0 && x_new < m && y_new >= 0 && y_new < n && !visited[x_new][y_new] && grid[x_new][y_new] == 0) {
                                visited[x_new][y_new] = true;
                                q.push({x_new, y_new});
                                dist_sum[x_new][y_new] += level;
                                total_count[x_new][y_new]++;
                            }
                        }
                    }
                    level++;
                }
            }
        }
    }

    int min_dist = INT_MAX;
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (total_count[i][j] == house_count) {
                min_dist = min(min_dist, dist_sum[i][j]);
            }
        }
    }

    return min_dist == INT_MAX ? -1 : min_dist;
}
