        for (int i = 0; i <= target.length() - stamp.length(); ++i) {
            if (isStamped[i]) continue;
            int j = 0;
            int overlap = 0;
            while (j < stamp.length() && (targetStr.charAt(i + j) == '?' || targetStr.charAt(i + j) == stamp.charAt(j))) {
