    public String decodeString(String s) {
        Stack<Integer> counts = new Stack<>();
        Stack<String> results = new Stack<>();
        String current = "";
        int ptr = 0;

        while (ptr < s.length()) {
            if (Character.isDigit(s.charAt(ptr))) {
                int count = 0;
                while (Character.isDigit(s.charAt(ptr))) {
                    count = count * 10 + (s.charAt(ptr) - '0');
