                result.push_back(i);
                isStamped[i] = true;
                found_stamp = true;
            }
        }
        if (!found_stamp)
            break;       

        stamp_count++;
    }
    for (char c : target)
        if (c != '?') return {};

    std::reverse(result.begin(), result.end());
    return result;
